/**
 * @fileOverview Schemas for the project description generation AI agent.
 */

import {z} from 'zod';

export const GenerateProjectDescriptionInputSchema = z.object({
  idea: z.string().describe('The project idea.'),
});
export type GenerateProjectDescriptionInput = z.infer<
  typeof GenerateProjectDescriptionInputSchema
>;

export const GenerateProjectDescriptionOutputSchema = z.object({
  title: z.string().describe('The title of the project.'),
  description: z.string().describe('The description of the project.'),
});
export type GenerateProjectDescriptionOutput = z.infer<
  typeof GenerateProjectDescriptionOutputSchema
>;
