'use client';

import {useState} from 'react';
import {useForm} from 'react-hook-form';
import {useToast} from '@/hooks/use-toast';
import {z} from 'zod';
import {zodResolver} from '@hookform/resolvers/zod';
import {
  GenerateProjectDescriptionInput,
  GenerateProjectDescriptionInputSchema,
} from '@/ai/schemas/generate-project-description';
import {generateProjectDescription} from '@/ai/flows/generate-project-description';
import {Button} from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import {Textarea} from '@/components/ui/textarea';
import {Wand2} from 'lucide-react';

export default function GenerateProjectDescription() {
  const {toast} = useToast();

  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState({title: '', description: ''});

  const form = useForm<GenerateProjectDescriptionInput>({
    resolver: zodResolver(GenerateProjectDescriptionInputSchema),
    defaultValues: {
      idea: '',
    },
  });

  async function onSubmit(values: z.infer<typeof GenerateProjectDescriptionInputSchema>) {
    try {
      setIsLoading(true);
      const result = await generateProjectDescription(values);
      setResult(result);
    } catch (error) {
      console.error(error);
      toast({
        title: 'Error',
        description: 'An error occurred while generating the project description.',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <Card className="max-w-2xl mx-auto">
      <CardHeader>
        <CardTitle className="flex items-center gap-2 font-headline">
          <Wand2 className="w-6 h-6 text-accent" />
          <span>AI Project Idea Generator</span>
        </CardTitle>
        <CardDescription>
          Have an idea for a project? Let AI help you flesh it out. Describe your
          idea, and we'll generate a title and description for you.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="idea"
              render={({field}) => (
                <FormItem>
                  <FormLabel>Project Idea</FormLabel>
                  <FormControl>
                    <Textarea
                      placeholder="e.g., A mobile app that uses AI to identify plants from photos."
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <Button type="submit" disabled={isLoading}>
              {isLoading ? 'Generating...' : 'Generate Description'}
            </Button>
          </form>
        </Form>
      </CardContent>
      {result.title && (
        <CardFooter className="flex-col items-start gap-4 border-t pt-6">
          <h3 className="font-bold font-headline text-lg">Generated Project</h3>
          <div className="space-y-2">
            <p><span className="font-semibold">Title:</span> {result.title}</p>
            <p><span className="font-semibold">Description:</span> {result.description}</p>
          </div>
        </CardFooter>
      )}
    </Card>
  );
}
